effects.fragment:
vec2 l__p = (v_tex_coord - vec2(0.5)) / u__scale;
float l__w = 0.54;
float l__h = 0.58;
vec2 l__front = vec2((l__p.x + 0.38) / l__w, (l__p.y + 0.16) / l__h);
float l__front_mask = step(0.0, l__front.x) * step(l__front.x, 1.0) * step(0.0, l__front.y) * step(l__front.y, 1.0);
vec2 l__right_delta = l__p - vec2(0.16, -0.16);
float l__right_u = l__right_delta.x / u__depth;
float l__right_v = (u__depth * l__right_delta.y + u__depth * 0.72 * l__right_delta.x) / (u__depth * l__h);
vec2 l__right = vec2(l__right_u, l__right_v);
float l__right_mask = step(0.0, l__right.x) * step(l__right.x, 1.0) * step(0.0, l__right.y) * step(l__right.y, 1.0);
vec2 l__top_delta = l__p - vec2(-0.38, -0.16);
float l__top_v = -l__top_delta.y / (u__depth * 0.72);
float l__top_u = (l__top_delta.x - u__depth * l__top_v) / l__w;
vec2 l__top = vec2(l__top_u, l__top_v);
float l__top_mask = step(0.0, l__top.x) * step(l__top.x, 1.0) * step(0.0, l__top.y) * step(l__top.y, 1.0);
vec2 l__crop_min = vec2(u__crop);
vec2 l__crop_max = vec2(1.0 - u__crop);
vec4 l__front_tex = texture2D(tex0, mix(l__crop_min, l__crop_max, clamp(l__front, 0.0, 1.0)));
vec4 l__right_tex = texture2D(tex0, mix(l__crop_min, l__crop_max, clamp(vec2(1.0 - l__right.x, l__right.y), 0.0, 1.0)));
vec4 l__top_tex = texture2D(tex0, mix(l__crop_min, l__crop_max, clamp(vec2(l__top.x, 1.0 - l__top.y), 0.0, 1.0)));
float l__front_edge = l__front_mask * (1.0 - smoothstep(0.0, 0.045, min(min(l__front.x, 1.0 - l__front.x), min(l__front.y, 1.0 - l__front.y))));
float l__right_edge = l__right_mask * (1.0 - smoothstep(0.0, 0.055, min(min(l__right.x, 1.0 - l__right.x), min(l__right.y, 1.0 - l__right.y))));
float l__top_edge = l__top_mask * (1.0 - smoothstep(0.0, 0.055, min(min(l__top.x, 1.0 - l__top.x), min(l__top.y, 1.0 - l__top.y))));
vec4 l__cube = vec4(0.0);
l__cube += vec4(mix(u__void_color, l__front_tex.rgb, 0.88), max(0.82, l__front_tex.a)) * l__front_mask;
l__cube = mix(l__cube, vec4(mix(u__void_color, l__right_tex.rgb * vec3(0.42, 0.82, 1.18), 0.84), max(0.82, l__right_tex.a)), l__right_mask);
l__cube = mix(l__cube, vec4(mix(u__void_color, l__top_tex.rgb * vec3(1.28, 0.72, 1.18), 0.84), max(0.82, l__top_tex.a)), l__top_mask);
float l__edge = max(l__front_edge, max(l__right_edge, l__top_edge));
l__cube.rgb += u__edge_color * l__edge * 0.55;
l__cube.a = max(l__cube.a, l__edge);
gl_FragColor = mix(gl_FragColor, l__cube, u__intensity);

vec2 l__grid = vec2(u__blocks, u__blocks);
vec2 l__cell = floor(v_tex_coord * l__grid);
vec2 l__local = fract(v_tex_coord * l__grid) - vec2(0.5);
vec2 l__center = (l__cell + vec2(0.5)) / l__grid;
float l__hash = fract(sin(dot(l__cell, vec2(127.1, 311.7))) * 43758.5453);
float l__hash2 = fract(sin(dot(l__cell, vec2(269.5, 183.3))) * 24634.6345);
float l__pulse = 0.5 + 0.5 * sin(u_time * u__speed + l__hash * 6.28318);
vec2 l__radial = l__center - vec2(0.5);
float l__shell = smoothstep(0.08, 0.68, length(l__radial));
vec2 l__source = l__center - l__radial * u__scatter * u__intensity * (0.28 + 0.72 * l__pulse) * l__shell;
l__source += vec2(l__hash - 0.5, l__hash2 - 0.5) * 0.055 * u__scatter * u__intensity;
vec4 l__cube = texture2D(tex0, clamp(l__source, vec2(0.001), vec2(0.999)));
float l__square = 1.0 - smoothstep(0.40, 0.49, max(abs(l__local.x), abs(l__local.y)));
float l__bevel = smoothstep(0.30, 0.47, max(abs(l__local.x), abs(l__local.y)));
float l__face = 0.72 + u__depth * (0.42 * l__local.x - 0.55 * l__local.y + 0.18 * (l__hash - 0.5));
l__cube.rgb *= max(0.18, l__face) * l__square;
l__cube.rgb += u__edge_color * l__bevel * l__square * l__cube.a * (0.18 + 0.35 * l__pulse) * u__depth;
l__cube.a *= l__square;
gl_FragColor = mix(gl_FragColor, l__cube, u__intensity);

vec2 l__p = v_tex_coord - vec2(0.5);
float l__radius = length(l__p);
float l__angle = atan(l__p.y, l__p.x) + u_time * u__speed + l__radius * u__twist;
float l__sector = 6.2831853 / max(3.0, u__folds);
float l__folded = abs(mod(l__angle + 0.5 * l__sector, l__sector) - 0.5 * l__sector);
vec2 l__warped = vec2(cos(l__folded), sin(l__folded)) * l__radius * u__core + vec2(0.5);
vec4 l__fold = texture2D(tex0, clamp(l__warped, vec2(0.001), vec2(0.999)));
float l__rim = pow(clamp(1.0 - abs(sin(l__angle * u__folds * 0.5)), 0.0, 1.0), 7.0);
l__fold.rgb = mix(l__fold.rgb, l__fold.rgb * u__color, 0.48 + 0.34 * l__rim);
l__fold.rgb += u__color * l__rim * l__fold.a * 0.22;
l__fold.a *= smoothstep(0.72, 0.05, l__radius);
gl_FragColor = mix(gl_FragColor, l__fold, u__intensity);

float l__breath = 0.72 + 0.28 * sin(u_time * u__speed);
vec2 l__offset = vec2(u__distance * l__breath * u__intensity, 0.012 * sin(u_time * u__speed * 1.7));
vec4 l__left = texture2D(tex0, clamp(v_tex_coord + l__offset, vec2(0.001), vec2(0.999)));
vec4 l__right = texture2D(tex0, clamp(v_tex_coord - l__offset, vec2(0.001), vec2(0.999)));
vec4 l__high = texture2D(tex0, clamp(v_tex_coord + vec2(0.0, u__distance * 0.65), vec2(0.001), vec2(0.999)));
vec4 l__low = texture2D(tex0, clamp(v_tex_coord - vec2(0.0, u__distance * 0.65), vec2(0.001), vec2(0.999)));
vec3 l__souls = l__left.rgb * u__cyan * 0.42 + l__right.rgb * u__magenta * 0.42;
l__souls += l__high.rgb * vec3(0.22, 0.08, 0.38) + l__low.rgb * vec3(0.06, 0.24, 0.34);
float l__alpha = max(max(l__left.a, l__right.a), max(l__high.a, l__low.a));
vec4 l__echo = vec4(l__souls, l__alpha);
gl_FragColor = mix(gl_FragColor, l__echo, u__intensity * 0.88);

float l__slice = floor(v_tex_coord.y * u__slices);
float l__hash = fract(sin(l__slice * 91.173 + floor(u_time * u__speed * 5.0) * 17.13) * 43758.5453);
float l__gate = step(0.54, l__hash) * (0.35 + 0.65 * fract(l__hash * 7.91));
float l__shift = (l__hash - 0.5) * 2.0 * u__distance * u__intensity * l__gate;
float l__jitter = sin(v_tex_coord.y * 930.0 + u_time * u__speed * 13.0) * 0.004 * u__intensity;
vec2 l__uv = clamp(v_tex_coord + vec2(l__shift + l__jitter, 0.0), vec2(0.001), vec2(0.999));
vec4 l__red = texture2D(tex0, clamp(l__uv + vec2(0.008 * u__intensity, 0.0), vec2(0.001), vec2(0.999)));
vec4 l__green = texture2D(tex0, l__uv);
vec4 l__blue = texture2D(tex0, clamp(l__uv - vec2(0.011 * u__intensity, 0.0), vec2(0.001), vec2(0.999)));
vec4 l__shred = vec4(l__red.r, l__green.g, l__blue.b, max(l__red.a, max(l__green.a, l__blue.a)));
float l__cut = step(0.92, fract(l__hash * 13.7 + v_tex_coord.x * 3.0));
l__shred.rgb = mix(l__shred.rgb, u__void_color * l__shred.a, l__cut * 0.72);
l__shred.a *= 1.0 - l__cut * 0.58 * u__intensity;
gl_FragColor = mix(gl_FragColor, l__shred, u__intensity);

float l__column = floor(v_tex_coord.x * u__frequency);
float l__hash = fract(sin(l__column * 71.319) * 43758.5453);
float l__wave = 0.5 + 0.5 * sin(u_time * u__speed + l__hash * 8.0);
float l__lower = smoothstep(0.28, 0.94, v_tex_coord.y);
float l__drop = u__drip * u__intensity * l__lower * (0.18 + 0.82 * l__hash) * (0.55 + 0.45 * l__wave);
vec2 l__melt_uv = v_tex_coord - vec2(sin(v_tex_coord.y * 17.0 + l__hash * 9.0) * 0.012 * u__intensity, l__drop);
vec4 l__melt = texture2D(tex0, clamp(l__melt_uv, vec2(0.001), vec2(0.999)));
vec4 l__ghost = texture2D(tex0, clamp(v_tex_coord + vec2(sin(v_tex_coord.y * 23.0 + u_time) * 0.025, -l__drop * 0.35), vec2(0.001), vec2(0.999)));
float l__vein = pow(0.5 + 0.5 * sin(v_tex_coord.x * u__frequency * 3.14159 + l__hash * 5.0), 9.0);
l__melt.rgb = mix(l__melt.rgb, l__melt.rgb * u__blood, l__lower * (0.28 + 0.55 * l__vein));
l__melt.rgb += l__ghost.rgb * u__blood * 0.16 * u__intensity;
l__melt.a = max(l__melt.a, l__ghost.a * 0.32 * u__intensity);
gl_FragColor = mix(gl_FragColor, l__melt, u__intensity);
